import json
import math
from collections import defaultdict

EMPLOYEES = [
    ("e00", "Engineering", 2), ("e01", "Finance", 2), ("e02", "Sales", 1), ("e03", "Legal", 3),
    ("e04", "Research", 3), ("e05", "Sales", 2), ("e06", "Legal", 3), ("e07", "Sales", 2),
    ("e08", "Finance", 1), ("e09", "Finance", 3), ("e10", "Engineering", 2), ("e11", "Legal", 3),
    ("e12", "Sales", 2), ("e13", "Engineering", 2), ("e14", "Engineering", 2), ("e15", "Engineering", 1),
    ("e16", "Research", 3), ("e17", "Finance", 3), ("e18", "Finance", 2), ("e19", "Sales", 2),
    ("e20", "Research", 3), ("e21", "Finance", 1), ("e22", "Engineering", 3), ("e23", "Finance", 1),
    ("e24", "Legal", 3), ("e25", "Engineering", 2), ("e26", "Research", 2), ("e27", "Sales", 2),
    ("e28", "Finance", 1), ("e29", "Sales", 1), ("e30", "Research", 2), ("e31", "Engineering", 1),
    ("e32", "Engineering", 2), ("e33", "Sales", 3), ("e34", "Research", 2), ("e35", "Research", 1),
    ("e36", "Sales", 1), ("e37", "Research", 3), ("e38", "Sales", 3), ("e39", "Sales", 3),
]

EMP_DEPT = {eid: dept for eid, dept, _ in EMPLOYEES}
ALL_EIDS = [eid for eid, _, _ in EMPLOYEES]
DECOY = "e27"

STATE_FILE = "/tmp/opencode/game_state.json"

def init_state():
    state = {
        "documents": {},   # doc_id -> {"day": int, "recipients": [...], "is_canary": bool, "assignment": {...}}
        "logs": [],        # list of {"day": int, "employee": str, "doc_id": str, "after_hours": bool}
        "interviews": [],  # list of {"day": int, "employee": str, "topic": str, "evasive": bool}
        "leaks": [],       # list of {"doc_id": str, "variant": str or None}
    }
    with open(STATE_FILE, "w") as f:
        json.dump(state, f, indent=2)

def compute_posteriors(state):
    log_p = {eid: 0.0 for eid in ALL_EIDS}
    log_p[DECOY] = -1e9

    # 1. Leaks
    for leak in state["leaks"]:
        doc_id = leak["doc_id"]
        variant = leak.get("variant")
        doc = state["documents"][doc_id]
        rec = set(doc["recipients"])
        for eid in ALL_EIDS:
            if eid not in rec:
                log_p[eid] = -1e9
        if doc["is_canary"] and variant is not None:
            assign = doc["assignment"]
            labels = set(assign.values())
            n_other = len(labels) - 1
            for eid in rec:
                if log_p[eid] <= -1e8:
                    continue
                if assign[eid] == variant:
                    log_p[eid] += math.log(0.95 if n_other > 0 else 1.0)
                else:
                    log_p[eid] += math.log(0.05 / n_other)

    # 2. Interviews
    for iv in state["interviews"]:
        eid = iv["employee"]
        if log_p[eid] <= -1e8:
            continue
        if iv["evasive"]:
            log_p[eid] += math.log(0.24 / 0.20)
        else:
            log_p[eid] += math.log(0.76 / 0.80)

    # 3. Access logs by day
    days_seen = sorted(set(l["day"] for l in state["logs"]))
    # Estimate non-decoy framing rate empirically or use conservative 0.135
    total_non_decoy_ah = sum(1 for l in state["logs"] if l["employee"] != DECOY and l["after_hours"])
    # Expected per day: 38 * r_inn + 0.3
    # Use r_inn = 0.135 (covers baseline 0.1263 and partial DSL random framing)
    r_inn_ah = 0.135
    r_inn_day = 0.90
    r_mole_ah = 0.30
    r_mole_day = 0.70

    counts = defaultdict(lambda: [0, 0])  # (eid, day) -> [k_day, k_ah]
    for l in state["logs"]:
        if l["after_hours"]:
            counts[(l["employee"], l["day"])][1] += 1
        else:
            counts[(l["employee"], l["day"])][0] += 1

    for d in days_seen:
        for eid in ALL_EIDS:
            if log_p[eid] <= -1e8:
                continue
            k_day, k_ah = counts[(eid, d)]
            llr = (
                k_day * math.log(r_mole_day / r_inn_day) - (r_mole_day - r_inn_day)
                + k_ah * math.log(r_mole_ah / r_inn_ah) - (r_mole_ah - r_inn_ah)
            )
            log_p[eid] += llr

    mx = max(log_p.values())
    probs = {eid: (math.exp(log_p[eid] - mx) if log_p[eid] > -1e8 else 0.0) for eid in ALL_EIDS}
    s = sum(probs.values())
    probs = {eid: probs[eid] / s for eid in ALL_EIDS}
    return probs

if __name__ == "__main__":
    init_state()
    print("Initialized state.")
